const Map<String, Map<String, String>> kExScreenText = {
  'guideTitleWatch': {'KO': '워치 연동 설정 방법', 'EN': 'WATCH SETUP GUIDE', 'JA': 'ウォッチ連携の設定方法', 'ZH': '手表连接设置方法', 'FR': 'Configurer la montre', 'DE': 'Uhr einrichten', 'RU': 'Настройка часов', 'AR': 'إعداد الساعة', 'HI': 'वॉच सेटअप गाइड', 'VI': 'Cách kết nối đồng hồ', 'ES': 'Configurar el reloj', 'TH': 'วิธีตั้งค่านาฬิกา'},
  'guideTitlePhone': {'KO': '폰 걸음수 설정 방법', 'EN': 'PHONE SETUP GUIDE', 'JA': 'スマホ歩数の設定方法', 'ZH': '手机计步设置方法', 'FR': 'Configurer le podomètre', 'DE': 'Schrittzähler einrichten', 'RU': 'Настройка шагомера', 'AR': 'إعداد عدّاد الخطوات', 'HI': 'फ़ोन स्टेप सेटअप', 'VI': 'Cách cài đếm bước trên điện thoại', 'ES': 'Configurar podómetro', 'TH': 'วิธีตั้งค่านับก้าวในโทรศัพท์'},
  'guideBodyWatch': {'KO': '워치 걸음수가 우리 앱까지 오려면 아래 3단계가 전부 되어 있어야 합니다.\n\n① 워치 ↔ 삼성헬스\n워치의 Galaxy Wearable 앱이 폰과 페어링되어 있고, 삼성헬스 앱에 실제 걸음수가 찍히는지 확인.\n\n② Health Connect 설치 + 동기화 켜기\n폰에 "Health Connect" 앱 설치(안드로이드 14+는 기본 내장) → 삼성헬스 앱 → 설정 → "Health Connect와 연결하기" → 걸음수 항목 토글 켜기.\n\n③ 우리 앱 권한 허용\n이 화면에서 워치를 처음 선택하면 권한 요청 팝업이 뜨는데 "허용"을 눌러야 함. 이미 거부했다면 Health Connect 앱 → 연결된 앱 → GKE StudyUp → 걸음수 읽기 권한 켜기.', 'EN': 'For watch steps to reach this app, all 3 steps below must be done.\n\n① Watch ↔ Samsung Health\nPair the watch with the phone in the Galaxy Wearable app and check that Samsung Health shows your steps.\n\n② Install Health Connect + turn on sync\nInstall "Health Connect" (built in on Android 14+) → Samsung Health → Settings → "Connect to Health Connect" → turn on Steps.\n\n③ Allow this app\nWhen you first pick Watch here, a permission pop-up appears — tap "Allow". If you denied it before: Health Connect → Connected apps → GKE StudyUp → turn on Steps read.', 'JA': 'ウォッチの歩数をこのアプリに届けるには、次の3つがすべて必要です。\n\n① ウォッチ ↔ Samsung Health\nGalaxy Wearable アプリでウォッチとスマホをペアリングし、Samsung Health に歩数が表示されるか確認。\n\n② Health Connect をインストール + 同期オン\n「Health Connect」をインストール（Android 14 以上は標準搭載）→ Samsung Health → 設定 →「Health Connect と連携」→ 歩数をオン。\n\n③ このアプリを許可\nここで初めてウォッチを選ぶと許可の画面が出るので「許可」をタップ。以前拒否した場合は Health Connect → 連携アプリ → GKE StudyUp → 歩数の読み取りをオン。', 'ZH': '要让手表步数传到本应用，以下 3 步都必须完成。\n\n① 手表 ↔ 三星健康\n在 Galaxy Wearable 应用中将手表与手机配对，并确认三星健康里能看到步数。\n\n② 安装 Health Connect 并开启同步\n安装“Health Connect”（Android 14 及以上已内置）→ 三星健康 → 设置 →“连接 Health Connect”→ 打开步数。\n\n③ 允许本应用\n首次在此选择手表时会弹出权限窗口，请点“允许”。如果之前拒绝过：Health Connect → 已连接应用 → GKE StudyUp → 打开步数读取。', 'FR': 'Pour que les pas de la montre arrivent dans l\'appli, les 3 étapes ci-dessous sont nécessaires.\n\n① Montre ↔ Samsung Health\nAssociez la montre au téléphone dans Galaxy Wearable et vérifiez que Samsung Health affiche vos pas.\n\n② Installer Health Connect + activer la synchro\nInstallez « Health Connect » (intégré à Android 14+) → Samsung Health → Paramètres → « Connecter à Health Connect » → activez Pas.\n\n③ Autoriser cette appli\nLa première fois que vous choisissez Montre ici, touchez « Autoriser ». Si vous avez refusé : Health Connect → Applis connectées → GKE StudyUp → activez la lecture des pas.', 'DE': 'Damit Uhr-Schritte in diese App kommen, müssen alle 3 Schritte erledigt sein.\n\n① Uhr ↔ Samsung Health\nUhr in der Galaxy Wearable App mit dem Handy koppeln und prüfen, ob Samsung Health Schritte zeigt.\n\n② Health Connect installieren + Sync einschalten\n„Health Connect“ installieren (ab Android 14 integriert) → Samsung Health → Einstellungen → „Mit Health Connect verbinden“ → Schritte einschalten.\n\n③ Diese App erlauben\nBeim ersten Wählen von „Uhr“ erscheint eine Abfrage – „Zulassen“ tippen. Falls abgelehnt: Health Connect → Verbundene Apps → GKE StudyUp → Schritte lesen einschalten.', 'RU': 'Чтобы шаги с часов попадали в приложение, нужны все 3 шага ниже.\n\n① Часы ↔ Samsung Health\nСопрягите часы с телефоном в Galaxy Wearable и проверьте, что Samsung Health показывает шаги.\n\n② Установите Health Connect и включите синхронизацию\nУстановите «Health Connect» (встроен в Android 14+) → Samsung Health → Настройки → «Подключить к Health Connect» → включите Шаги.\n\n③ Разрешите приложению\nПри первом выборе «Часы» появится запрос — нажмите «Разрешить». Если вы отказали: Health Connect → Подключённые приложения → GKE StudyUp → включите чтение шагов.', 'AR': 'لكي تصل خطوات الساعة إلى التطبيق يجب إتمام الخطوات الثلاث التالية.\n\n① الساعة ↔ Samsung Health\nاقرن الساعة بالهاتف في تطبيق Galaxy Wearable وتأكد من ظهور خطواتك في Samsung Health.\n\n② ثبّت Health Connect وفعّل المزامنة\nثبّت «Health Connect» (مدمج في Android 14 وما بعده) ← Samsung Health ← الإعدادات ← «الاتصال بـ Health Connect» ← فعّل الخطوات.\n\n③ اسمح لهذا التطبيق\nعند اختيار الساعة أول مرة تظهر نافذة إذن، اضغط «سماح». إن رفضت سابقًا: Health Connect ← التطبيقات المتصلة ← GKE StudyUp ← فعّل قراءة الخطوات.', 'HI': 'वॉच के कदम इस ऐप तक आने के लिए नीचे के 3 चरण पूरे होने चाहिए।\n\n① वॉच ↔ Samsung Health\nGalaxy Wearable ऐप में वॉच को फ़ोन से जोड़ें और देखें कि Samsung Health में कदम दिख रहे हैं।\n\n② Health Connect इंस्टॉल करें + सिंक चालू करें\n"Health Connect" इंस्टॉल करें (Android 14+ में पहले से है) → Samsung Health → सेटिंग्स → "Health Connect से जोड़ें" → कदम चालू करें।\n\n③ इस ऐप को अनुमति दें\nयहाँ पहली बार वॉच चुनने पर अनुमति विंडो आएगी — "अनुमति दें" दबाएँ। पहले मना किया हो तो: Health Connect → जुड़े ऐप → GKE StudyUp → कदम पढ़ना चालू करें।', 'VI': 'Để số bước từ đồng hồ đến được ứng dụng, cần làm đủ 3 bước dưới đây.\n\n① Đồng hồ ↔ Samsung Health\nGhép đôi đồng hồ với điện thoại trong Galaxy Wearable và kiểm tra Samsung Health có hiện số bước.\n\n② Cài Health Connect + bật đồng bộ\nCài "Health Connect" (Android 14+ có sẵn) → Samsung Health → Cài đặt → "Kết nối với Health Connect" → bật Số bước.\n\n③ Cho phép ứng dụng này\nLần đầu chọn Đồng hồ ở đây sẽ hiện cửa sổ cấp quyền — chạm "Cho phép". Nếu đã từ chối: Health Connect → Ứng dụng đã kết nối → GKE StudyUp → bật đọc Số bước.', 'ES': 'Para que los pasos del reloj lleguen a la app, deben cumplirse los 3 pasos siguientes.\n\n① Reloj ↔ Samsung Health\nVincula el reloj con el móvil en Galaxy Wearable y comprueba que Samsung Health muestra tus pasos.\n\n② Instala Health Connect + activa la sincronización\nInstala «Health Connect» (incluido en Android 14+) → Samsung Health → Ajustes → «Conectar con Health Connect» → activa Pasos.\n\n③ Permite esta app\nLa primera vez que elijas Reloj aparecerá un aviso: toca «Permitir». Si lo rechazaste: Health Connect → Apps conectadas → GKE StudyUp → activa leer Pasos.', 'TH': 'เพื่อให้จำนวนก้าวจากนาฬิกามาถึงแอปนี้ ต้องทำครบ 3 ขั้นตอนด้านล่าง\n\n① นาฬิกา ↔ Samsung Health\nจับคู่นาฬิกากับโทรศัพท์ในแอป Galaxy Wearable และตรวจว่า Samsung Health แสดงจำนวนก้าว\n\n② ติดตั้ง Health Connect + เปิดซิงค์\nติดตั้ง "Health Connect" (Android 14 ขึ้นไปมีในเครื่อง) → Samsung Health → การตั้งค่า → "เชื่อมต่อกับ Health Connect" → เปิดจำนวนก้าว\n\n③ อนุญาตแอปนี้\nเมื่อเลือกนาฬิกาครั้งแรกจะมีหน้าต่างขออนุญาต ให้แตะ "อนุญาต" หากเคยปฏิเสธ: Health Connect → แอปที่เชื่อมต่อ → GKE StudyUp → เปิดการอ่านจำนวนก้าว'},
  'guideBodyPhone': {'KO': '폰 자체 걸음수 센서를 쓰려면 아래가 되어 있어야 합니다.\n\n① 신체 활동 권한 허용\n안드로이드 10 이상은 "신체 활동(걸음 수)" 권한을 허용해야 걸음수 센서를 읽을 수 있습니다. 처음 폰을 선택하면 권한 팝업이 뜨는데 "허용"을 눌러주세요.\n\n② 이미 거부했다면\n설정 → 앱 → GKE StudyUp → 권한 → 신체 활동 → 허용으로 변경.\n\n③ 측정 중엔 폰을 몸에 지니고 있기\n주머니나 손에 들고 걸어야 센서가 걸음을 인식합니다.', 'EN': 'To use the phone\'s own step sensor:\n\n① Allow Physical activity\nOn Android 10+, the "Physical activity" permission is needed to read steps. When you first pick Phone, a pop-up appears — tap "Allow".\n\n② If you denied it before\nSettings → Apps → GKE StudyUp → Permissions → Physical activity → Allow.\n\n③ Keep the phone on you\nCarry it in your pocket or hand while walking so the sensor can count steps.', 'JA': 'スマホ本体の歩数センサーを使うには次が必要です。\n\n① 身体活動の許可\nAndroid 10 以上では「身体活動」の許可がないと歩数を読めません。初めてスマホを選ぶと許可の画面が出るので「許可」をタップ。\n\n② 以前拒否した場合\n設定 → アプリ → GKE StudyUp → 権限 → 身体活動 → 許可。\n\n③ 計測中はスマホを身につける\nポケットや手に持って歩くとセンサーが歩数を数えます。', 'ZH': '要使用手机自带计步传感器，需要：\n\n① 允许“身体活动”权限\nAndroid 10 及以上必须允许“身体活动”才能读取步数。首次选择手机时会弹出权限窗口，请点“允许”。\n\n② 如果之前拒绝过\n设置 → 应用 → GKE StudyUp → 权限 → 身体活动 → 允许。\n\n③ 测量时随身携带手机\n放在口袋或手里走路，传感器才能识别步数。', 'FR': 'Pour utiliser le capteur de pas du téléphone :\n\n① Autoriser « Activité physique »\nSur Android 10+, cette autorisation est nécessaire pour lire les pas. La première fois que vous choisissez Téléphone, touchez « Autoriser ».\n\n② Si vous avez refusé\nParamètres → Applis → GKE StudyUp → Autorisations → Activité physique → Autoriser.\n\n③ Gardez le téléphone sur vous\nDans la poche ou à la main pendant la marche pour que les pas soient comptés.', 'DE': 'So nutzt du den Schrittsensor des Handys:\n\n① „Körperliche Aktivität“ erlauben\nAb Android 10 ist diese Berechtigung zum Lesen der Schritte nötig. Beim ersten Wählen von „Handy“ „Zulassen“ tippen.\n\n② Falls abgelehnt\nEinstellungen → Apps → GKE StudyUp → Berechtigungen → Körperliche Aktivität → Zulassen.\n\n③ Handy bei dir tragen\nIn der Tasche oder Hand tragen, damit der Sensor die Schritte zählt.', 'RU': 'Чтобы использовать датчик шагов телефона:\n\n① Разрешите «Физическая активность»\nНа Android 10+ без этого разрешения шаги не читаются. При первом выборе «Телефон» нажмите «Разрешить».\n\n② Если вы отказали\nНастройки → Приложения → GKE StudyUp → Разрешения → Физическая активность → Разрешить.\n\n③ Держите телефон при себе\nВ кармане или в руке во время ходьбы, чтобы датчик считал шаги.', 'AR': 'لاستخدام مستشعر الخطوات في الهاتف:\n\n① اسمح بإذن «النشاط البدني»\nفي Android 10 وما بعده يلزم هذا الإذن لقراءة الخطوات. عند اختيار الهاتف أول مرة اضغط «سماح».\n\n② إن رفضت سابقًا\nالإعدادات ← التطبيقات ← GKE StudyUp ← الأذونات ← النشاط البدني ← سماح.\n\n③ احمل الهاتف معك\nفي جيبك أو يدك أثناء المشي ليحسب المستشعر خطواتك.', 'HI': 'फ़ोन का अपना स्टेप सेंसर इस्तेमाल करने के लिए:\n\n① "शारीरिक गतिविधि" अनुमति दें\nAndroid 10+ में कदम पढ़ने के लिए यह अनुमति ज़रूरी है। पहली बार फ़ोन चुनने पर "अनुमति दें" दबाएँ।\n\n② पहले मना किया हो तो\nसेटिंग्स → ऐप्स → GKE StudyUp → अनुमतियाँ → शारीरिक गतिविधि → अनुमति दें।\n\n③ फ़ोन साथ रखें\nचलते समय जेब या हाथ में रखें ताकि सेंसर कदम गिन सके।', 'VI': 'Để dùng cảm biến bước của điện thoại:\n\n① Cho phép "Hoạt động thể chất"\nTừ Android 10 cần quyền này để đọc số bước. Lần đầu chọn Điện thoại, hãy chạm "Cho phép".\n\n② Nếu đã từ chối\nCài đặt → Ứng dụng → GKE StudyUp → Quyền → Hoạt động thể chất → Cho phép.\n\n③ Mang điện thoại theo người\nĐể trong túi hoặc cầm tay khi đi để cảm biến đếm bước.', 'ES': 'Para usar el sensor de pasos del móvil:\n\n① Permite «Actividad física»\nEn Android 10+ este permiso es necesario para leer los pasos. La primera vez que elijas Móvil, toca «Permitir».\n\n② Si lo rechazaste\nAjustes → Aplicaciones → GKE StudyUp → Permisos → Actividad física → Permitir.\n\n③ Lleva el móvil contigo\nEn el bolsillo o en la mano al caminar para que el sensor cuente los pasos.', 'TH': 'หากต้องการใช้เซ็นเซอร์นับก้าวของโทรศัพท์:\n\n① อนุญาต "กิจกรรมทางกาย"\nAndroid 10 ขึ้นไปต้องอนุญาตสิทธิ์นี้จึงจะอ่านจำนวนก้าวได้ เมื่อเลือกโทรศัพท์ครั้งแรกให้แตะ "อนุญาต"\n\n② หากเคยปฏิเสธ\nการตั้งค่า → แอป → GKE StudyUp → สิทธิ์ → กิจกรรมทางกาย → อนุญาต\n\n③ พกโทรศัพท์ติดตัว\nใส่กระเป๋าหรือถือไว้ขณะเดิน เพื่อให้เซ็นเซอร์นับก้าวได้'},
  'hideToday': {'KO': '오늘 그만 보기', 'EN': 'Don\'t show today', 'JA': '今日は表示しない', 'ZH': '今天不再显示', 'FR': 'Ne plus afficher aujourd\'hui', 'DE': 'Heute nicht mehr zeigen', 'RU': 'Не показывать сегодня', 'AR': 'لا تعرض اليوم', 'HI': 'आज न दिखाएँ', 'VI': 'Hôm nay không hiện nữa', 'ES': 'No mostrar hoy', 'TH': 'ไม่ต้องแสดงวันนี้'},
