/// 지금 고른 언어로 글자 하나 꺼내기. args = {'n': 123} 처럼 빈자리 채우기
String exText(String key, [Map<String, Object>? args]) {
  final Map<String, String>? row = kExScreenText[key];
  String s = row?[appLanguage.current] ?? row?['EN'] ?? key;
  args?.forEach((k, v) => s = s.replaceAll('{$k}', v.toString()));
  return s;
}

/// 언어를 직접 지정해서 꺼내기 (한국어 모드의 '위 영문 · 아래 한글' 두 줄용)
String exTextIn(String key, String lang, [Map<String, Object>? args]) {
  final Map<String, String>? row = kExScreenText[key];
  String s = row?[lang] ?? row?['EN'] ?? key;
  args?.forEach((k, v) => s = s.replaceAll('{$k}', v.toString()));
  return s;
}

/// BiInline 의 translations 칸에 넣는 10개 외국어 표
Map<String, String> exTextTranslations(String key) {
  final Map<String, String> row = kExScreenText[key] ?? const {};
  return Map<String, String>.fromEntries(row.entries.where((e) => e.key != 'KO' && e.key != 'EN'));
}

