/// 헬스 추천 운동 이름을 지금 언어로 (한국어면 그대로)
String gymMoveLabel(String koName) {
  if (appLanguage.isDefault) return koName;
  final Map<String, String>? row = kGymMoveNames[koName];
  return row?[appLanguage.current] ?? row?['EN'] ?? koName;
}

