/// 단위를 지금 언어로 (한국어면 그대로, 표에 없는 단위(km · kg 등)도 그대로)
String exUnit(String? unit) {
  if (unit == null) return '';
  if (appLanguage.isDefault) return unit;
  final Map<String, String>? row = kExUnitNames[unit];
  return row?[appLanguage.current] ?? row?['EN'] ?? unit;
}

