/// 앱이 자동으로 적어 넣는 메모 글자를 지금 언어로 (사용자가 직접 쓴 메모는 그대로)
String exAutoMemo(String memo) {
  if (appLanguage.isDefault) return memo;
  const Map<String, String> known = {
    '⌚ 자동 기록 (삼성헬스·폰 중 많은 걸음)': 'memoAutoSteps',
    '자동 기록 (만보기, 매일 자동)': 'memoAutoLegacy',
    '⌚ 워치 운동 자동 기록 (삼성헬스)': 'memoAutoWorkout',
  };
  final String? key = known[memo.trim()];
  return key == null ? memo : exText(key);
}
